      }
    </style>
  </head>
  <body>
    <dialog open>
      <div class="chat-container">
        <div class="chat-header">
          Chatbot Falso
        </div>
        <div class="chat-history">
          <div class="chat-message">
            <p class="chat-message__human">Hola, ¿cómo puedo ayudarte?</p>
          </div>
          <div class="chat-message">
            <p class="chat-message__bot">Encantado de poder ayudarte. ¿Cuál es tu pregunta?</p>
