```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToCount; // palabra a contar
    string line; // línea del archivo

    // Solicitar palabra a contar al usuario
    cout << "Introduzca la palabra a contar: ";
    cin >> wordToCount;

    // Abrir el archivo para leer
    ifstream file("archivo.txt");

    if (!file.is_open()) { // Comprobar si se abrió correctamente el archivo
        cout << "Error al abrir el archivo." << endl;
        return 1;
    }

    int count = 0; // Contador de apariciones de la palabra

    // Leer línea por línea del archivo
    while (getline(file, line)) {
        // Buscar la palabra en la línea actual
        size_t pos = line.find(wordToCount);
        while (pos != string::npos) {
            count++; // Incrementar el contador de apariciones
            pos = line.find(wordToCount, pos + 1); // Buscar la siguiente aparición
        }
    }

    // Cerrar el archivo
    file.close();

    // Mostrar el resultado
    cout << "La palabra \"" << wordToCount << "\" aparece " << count << " veces en el archivo." << endl;

    return 0;
}
